import CoreGraphics
import CoreText
import Foundation

/// Shared Quantum Terminal scene renderer.
///
/// The static vault environment is generated by `QuantumArtwork` and shipped as
/// an 8K PNG. This renderer adds the animated security layer on top: radar dome,
/// energy rings, shield/lock core, orbital and pylon traffic, particles and HUD.
///
/// Every animated term is periodic over `loopDuration`, so the live desktop and
/// the 30-second HEVC loop are identical and the movie loops seamlessly.
enum QuantumScene {
    static let loopDuration: Double = 30.0
    static let omega: Double = (Double.pi * 2.0) / loopDuration
    static let irisRadiusFactor: CGFloat = 0.285
    static let coreCenterYFactor: CGFloat = 0.555

    /// Live-app hint: 0 when the user has been idle, rising toward 1 right after
    /// input. The renderer uses it to make the digital rain brighten and speed up
    /// briefly. The movie/preview renderers leave it at 0 for determinism.
    static var activity: CGFloat = 0.0

    /// The animated overlay is split into two passes so the live app can draw
    /// heavy vector geometry at a reduced backing scale while keeping text at
    /// full Retina resolution. The movie and preview renderers run both passes
    /// back to back into the same context.
    enum OverlayPhase {
        case geometry
        case text
    }

    // MARK: - Palette

    private enum C {
        static let black = CGColor(red: 0.002, green: 0.004, blue: 0.003, alpha: 1)
        static let deep = CGColor(red: 0.008, green: 0.035, blue: 0.020, alpha: 1)
        static let cyan = CGColor(red: 0.000, green: 1.000, blue: 0.250, alpha: 1)
        static let ice = CGColor(red: 0.820, green: 1.000, blue: 0.900, alpha: 1)
        static let blue = CGColor(red: 0.000, green: 0.550, blue: 0.300, alpha: 1)
        static let violet = CGColor(red: 0.320, green: 1.000, blue: 0.520, alpha: 1)
        static let red = CGColor(red: 1.000, green: 0.140, blue: 0.400, alpha: 1)
        static let amber = CGColor(red: 0.800, green: 1.000, blue: 0.300, alpha: 1)
        static let matrix = CGColor(red: 0.000, green: 1.000, blue: 0.250, alpha: 1)
    }

    private static func a(_ color: CGColor, _ alpha: CGFloat) -> CGColor {
        color.copy(alpha: alpha) ?? color
    }

    // MARK: - Entry point

    static func render(_ ctx: CGContext,
                       size: CGSize,
                       time rawTime: Double,
                       base: CGImage? = nil,
                       detail: Double = 1.0,
                       wallClock: Date? = nil) {
        let t = ((rawTime.truncatingRemainder(dividingBy: loopDuration)) + loopDuration)
            .truncatingRemainder(dividingBy: loopDuration)
        let w = size.width
        let h = size.height
        let s = min(w, h)
        let center = CGPoint(x: w * 0.5, y: h * coreCenterYFactor)
        let irisR = s * irisRadiusFactor

        ctx.saveGState()
        ctx.setAllowsAntialiasing(true)
        ctx.interpolationQuality = .high

        // The live app composites the static master in its own layer so the
        // wall server can move it without redrawing it. The movie and preview
        // renderers still pass the master here and get a complete frame.
        if let base {
            ctx.setBlendMode(.normal)
            ctx.setFillColor(C.black)
            ctx.fill(CGRect(origin: .zero, size: size))

            // Base environment with a barely perceptible camera breath and drift.
            let breath = 1.002 + 0.003 * CGFloat(cos(t * omega))
            let scale = max(w / CGFloat(base.width), h / CGFloat(base.height)) * breath
            let drawW = CGFloat(base.width) * scale
            let drawH = CGFloat(base.height) * scale
            let driftX = CGFloat(sin(t * omega)) * s * 0.0013
            let driftY = CGFloat(cos(t * omega)) * s * 0.0009
            ctx.draw(base, in: CGRect(x: (w - drawW) * 0.5 + driftX,
                                      y: (h - drawH) * 0.5 + driftY,
                                      width: drawW,
                                      height: drawH))
        }

        drawOverlay(ctx, size: size, center: center, irisR: irisR, t: t,
                    detail: detail, wallClock: wallClock, phase: .geometry)
        drawOverlay(ctx, size: size, center: center, irisR: irisR, t: t,
                    detail: detail, wallClock: wallClock, phase: .text)

        ctx.restoreGState()
    }

    /// Geometry-only pass for the live desktop. Draw into a context sized at
    /// the reduced overlay resolution; the text pass is composited separately.
    static func renderOverlayGeometry(_ ctx: CGContext, size: CGSize,
                                      time rawTime: Double,
                                      detail: Double = 1.0,
                                      wallClock: Date? = nil) {
        let t = ((rawTime.truncatingRemainder(dividingBy: loopDuration)) + loopDuration)
            .truncatingRemainder(dividingBy: loopDuration)
        let w = size.width, h = size.height, s = min(w, h)
        let center = CGPoint(x: w * 0.5, y: h * coreCenterYFactor)
        let irisR = s * irisRadiusFactor
        ctx.saveGState()
        ctx.setAllowsAntialiasing(true)
        ctx.interpolationQuality = .high
        drawOverlay(ctx, size: size, center: center, irisR: irisR, t: t,
                    detail: detail, wallClock: wallClock, phase: .geometry)
        ctx.restoreGState()
    }

    /// Text-only pass for the live desktop, drawn at full Retina resolution.
    static func renderOverlayText(_ ctx: CGContext, size: CGSize,
                                  time rawTime: Double,
                                  wallClock: Date? = nil) {
        let t = ((rawTime.truncatingRemainder(dividingBy: loopDuration)) + loopDuration)
            .truncatingRemainder(dividingBy: loopDuration)
        let w = size.width, h = size.height, s = min(w, h)
        let center = CGPoint(x: w * 0.5, y: h * coreCenterYFactor)
        let irisR = s * irisRadiusFactor
        ctx.saveGState()
        ctx.setAllowsAntialiasing(true)
        ctx.interpolationQuality = .high
        drawOverlay(ctx, size: size, center: center, irisR: irisR, t: t,
                    detail: 1.0, wallClock: wallClock, phase: .text)
        ctx.restoreGState()
    }

    private static func drawOverlay(_ ctx: CGContext, size: CGSize,
                                    center: CGPoint, irisR: CGFloat, t: Double,
                                    detail: Double, wallClock: Date?,
                                    phase: OverlayPhase) {
        ctx.setBlendMode(.screen)
        ctx.setLineCap(.round)
        ctx.setLineJoin(.round)

        if phase == .geometry {
            drawDepthRays(ctx, size: size, center: center, time: t)
            drawTunnel(ctx, size: size, center: center, time: t)
            drawLightSweep(ctx, size: size, center: center, time: t)
            drawEchoRadar(ctx, size: size, center: center, time: t)
            drawDepthDust(ctx, size: size, center: center, time: t)
            drawTwinkle(ctx, size: size, time: t)
            drawMatrixRain(ctx, size: size, time: t)
            drawRadar(ctx, size: size, center: center, time: t, detail: detail)
            drawBeam(ctx, size: size, center: center, irisR: irisR, time: t)
            drawEnergyRings(ctx, size: size, center: center, irisR: irisR, time: t)
            drawCore(ctx, size: size, center: center, time: t)
            drawOrbitalTraffic(ctx, size: size, center: center, irisR: irisR, time: t)
            drawPylonTraffic(ctx, size: size, time: t)
            drawParticles(ctx, size: size, time: t)
            drawThreatPings(ctx, size: size, center: center, irisR: irisR, time: t)
            drawScanSweep(ctx, size: size, time: t)
            drawDataStreams(ctx, size: size, time: t)
        } else {
            drawCodeRain(ctx, size: size, time: t)
        }

        drawChrono(ctx, size: size, time: t, wallClock: wallClock, phase: phase)
        drawTelemetry(ctx, size: size, time: t, phase: phase)
        drawProcessTable(ctx, size: size, time: t, phase: phase)
        drawThreatBadge(ctx, size: size, time: t, phase: phase)
        drawTerminal(ctx, size: size, time: t, wallClock: wallClock, phase: phase)
        drawTrace(ctx, size: size, time: t, phase: phase)
        drawHexDump(ctx, size: size, time: t, phase: phase)
        drawTicker(ctx, size: size, time: t, phase: phase)
        drawHUD(ctx, size: size, time: t, phase: phase)
        drawAlert(ctx, size: size, time: t, phase: phase)

        if phase == .geometry {
            drawBokeh(ctx, size: size, time: t)
            drawScanlines(ctx, size: size)
        } else {
            drawGlitch(ctx, size: size, time: t)
        }
    }

    // MARK: - Depth void (Matrix backdrop)

    /// Faint rays radiating from the vanishing point, like light bleeding down
    /// an endless corridor. A second, deeper vanishing layer behind the frames.
    private static func drawDepthRays(_ ctx: CGContext, size: CGSize,
                                      center: CGPoint, time: Double) {
        let s = min(size.width, size.height)
        let rays = 28
        ctx.setLineWidth(max(1, s * 0.0005))
        ctx.setStrokeColor(a(C.matrix, 0.055))
        let path = CGMutablePath()
        for i in 0..<rays {
            let base = Double(i) / Double(rays) * Double.pi * 2.0
            let jitter = rand(i * 13 + 9) * 0.10
            let ang = base + jitter
            let dirX = CGFloat(cos(ang))
            let dirY = CGFloat(sin(ang))
            let len = s * (0.55 + rand(i * 7 + 1) * 0.45)
            path.move(to: CGPoint(x: center.x + dirX * s * 0.02,
                                  y: center.y + dirY * s * 0.02))
            path.addLine(to: CGPoint(x: center.x + dirX * len,
                                     y: center.y + dirY * len))
        }
        ctx.addPath(path)
        ctx.strokePath()
    }

    /// A receding corridor of light converging on the core, drawn behind the
    /// radar so the vault reads as floating in an infinite, fog-filled void.
    private static func drawTunnel(_ ctx: CGContext, size: CGSize,
                                   center: CGPoint, time: Double) {
        let s = min(size.width, size.height)

        // Vanishing point: a bright core with a soft halo (filled, not shaded,
        // so the large-area glow stays cheap).
        let core = s * 0.020
        ctx.setFillColor(a(C.matrix, 0.55))
        ctx.fillEllipse(in: CGRect(x: center.x - core, y: center.y - core,
                                   width: core * 2, height: core * 2))
        let halo = s * 0.16
        ctx.setFillColor(a(C.matrix, 0.06))
        ctx.fillEllipse(in: CGRect(x: center.x - halo, y: center.y - halo,
                                   width: halo * 2, height: halo * 2))

        // Perspective frames: geometrically spaced rectangles that crowd toward
        // the vanishing point, brightening with depth cue toward the horizon.
        let frames = 12
        ctx.setLineWidth(max(1, s * 0.0008))
        for i in 0..<frames {
            let u = CGFloat(i) / CGFloat(frames - 1)
            let inset = s * 0.12 * pow(1.46, Double(i) * 1.5)
            let rect = CGRect(x: center.x - inset, y: center.y - inset,
                              width: inset * 2, height: inset * 2)
            ctx.setStrokeColor(a(C.matrix, 0.015 + 0.05 * u))
            ctx.stroke(rect)
        }
    }

    /// Two parallax layers of drifting dust: a far, faint field and a near,
    /// larger field. Sells the sense of massive, empty depth behind the vault.
    private static func drawDepthDust(_ ctx: CGContext, size: CGSize,
                                      center: CGPoint, time: Double) {
        let w = size.width, h = size.height
        let s = min(w, h)
        let layers: [(count: Int, size: CGFloat, speed: Double, alpha: CGFloat)] = [
            (110, s * 0.0011, 0.16, 0.07),
            (34, s * 0.0022, 0.55, 0.11)
        ]
        for (count, dot, speed, alpha) in layers {
            ctx.setFillColor(a(C.matrix, alpha))
            for i in 0..<count {
                let fx = rand(i * 3 + 1)
                let fy = rand(i * 7 + 2)
                let fz = rand(i * 11 + 5)
                let driftX = (time / loopDuration * speed + fx).truncatingRemainder(dividingBy: 1.0)
                let driftY = (time / loopDuration * speed * 0.6 + fy).truncatingRemainder(dividingBy: 1.0)
                let x = CGFloat(driftX) * w
                let y = CGFloat(driftY) * h
                let size = dot * (0.6 + CGFloat(fz) * 1.4)
                ctx.fill(CGRect(x: x, y: y, width: size, height: size))
            }
        }
    }

    /// A faint curtain of Matrix-style digital rain filling the void behind the
    /// vault. Two parallax layers — a tall, faint far field and a short, brighter
    /// near field — reinforce the depth. Glyphs only, fully periodic over the loop.
    private static func drawMatrixRain(_ ctx: CGContext, size: CGSize, time: Double) {
        let w = size.width, h = size.height
        let s = min(w, h)
        let layers: [(cols: Int, font: CGFloat, trail: Int, speed: Double, headAlpha: CGFloat)] = [
            (22, s * 0.0062, 4, 0.75, 0.46),
            (6, s * 0.0102, 3, 1.25, 0.60)
        ]

        for (cols, fontSize, trailCount, speedBase, headAlpha) in layers {
            let colW = w / CGFloat(cols)
            let rowStep = fontSize * 1.16
            let advance = textWidth("0", size: fontSize, kern: 0)
            let boost = 1.0 + activity * 0.7
            for c in 0..<cols {
                let x = colW * (CGFloat(c) + 0.5)
                let speed = speedBase * boost * (0.55 + 0.45 * rand(c * 17 + 3))
                let phase = rand(c * 29 + 7)
                let p = (time / loopDuration * speed + phase).truncatingRemainder(dividingBy: 1.0)
                let headY = h * (1.06 - CGFloat(p))
                let headIndex = (Int(time / loopDuration * 46.0) + c * 5) % matrixGlyphs.count
                let headAlphaBoost = headAlpha * (1.0 + activity * 0.4)

                let head = String(matrixGlyphs[headIndex])
                drawLabel(ctx, head, at: CGPoint(x: x - advance * 0.5, y: headY),
                          size: fontSize, color: a(C.matrix, min(0.75, headAlphaBoost)),
                          rightAligned: false, kern: 0)
                for k in 1...trailCount {
                    let gi = (headIndex + k * 13) % matrixGlyphs.count
                    let glyph = String(matrixGlyphs[gi])
                    let gy = headY - CGFloat(k) * rowStep
                    let fade = CGFloat(k) / CGFloat(trailCount + 1)
                    let alpha = headAlphaBoost * (1.0 - fade) * (1.0 - fade)
                    drawLabel(ctx, glyph, at: CGPoint(x: x - advance * 0.5, y: gy),
                              size: fontSize, color: a(C.matrix, alpha),
                              rightAligned: false, kern: 0)
                }
            }
        }
    }

    /// Slowly pulsing green motes in the void, giving the far background a
    /// sense of life beyond the drifting dust.
    private static func drawTwinkle(_ ctx: CGContext, size: CGSize, time: Double) {
        let w = size.width, h = size.height
        let s = min(w, h)
        for i in 0..<24 {
            let fx = rand(i * 53 + 2)
            let fy = rand(i * 59 + 4)
            let x = CGFloat(fx) * w
            let y = CGFloat(fy) * h
            let tw = 0.5 + 0.5 * sin(time * omega * (3.0 + rand(i * 71) * 5.0) + rand(i * 61) * 6.28)
            let r = s * (0.0008 + 0.0012 * rand(i * 67))
            ctx.setFillColor(a(C.matrix, CGFloat(0.02 + 0.10 * tw)))
            ctx.fill(CGRect(x: x, y: y, width: r * 2, height: r * 2))
        }
    }

    /// Near-field bokeh: a few large, faint green discs drifting in front of the
    /// vault (but behind the HUD text), so the camera feels suspended in the void.
    private static func drawBokeh(_ ctx: CGContext, size: CGSize, time: Double) {
        let w = size.width, h = size.height
        let s = min(w, h)
        for i in 0..<9 {
            let fx = rand(i * 31 + 1)
            let fy = rand(i * 37 + 2)
            let fz = rand(i * 41 + 3)
            let px = (fx + (time / loopDuration) * (0.03 + 0.02 * fz)).truncatingRemainder(dividingBy: 1.0)
            let py = (fy + (time / loopDuration) * (0.02 + 0.015 * fz)).truncatingRemainder(dividingBy: 1.0)
            let x = CGFloat(px) * w
            let y = CGFloat(py) * h
            let r = s * (0.035 + 0.030 * fz)
            let alpha = 0.006 + 0.012 * fz
            ctx.setFillColor(a(C.matrix, CGFloat(alpha)))
            ctx.fillEllipse(in: CGRect(x: x - r, y: y - r, width: r * 2, height: r * 2))
        }
    }

    /// A slow shaft of light sweeping the void from the core — one revolution
    /// per loop, so it stays seamless. A single flat wedge keeps it cheap.
    private static func drawLightSweep(_ ctx: CGContext, size: CGSize,
                                       center: CGPoint, time: Double) {
        let ang = CGFloat(time * omega)
        let half = CGFloat.pi * 0.085
        let outer = min(size.width, size.height) * 0.72
        let path = CGMutablePath()
        path.move(to: center)
        let steps = 8
        for j in 0...steps {
            let a = ang - half + (CGFloat(j) / CGFloat(steps)) * (half * 2.0)
            path.addLine(to: CGPoint(x: center.x + cos(a) * outer,
                                     y: center.y + sin(a) * outer))
        }
        path.closeSubpath()
        ctx.setFillColor(a(C.matrix, 0.028))
        ctx.addPath(path)
        ctx.fillPath()
    }

    /// A faint, off-centre sister dish behind the main radar — a second depth
    /// plane for the hologram.
    private static func drawEchoRadar(_ ctx: CGContext, size: CGSize,
                                      center: CGPoint, time: Double) {
        let s = min(size.width, size.height)
        let ec = CGPoint(x: center.x - s * 0.07, y: center.y + s * 0.035)
        let r = s * 0.23
        ctx.setStrokeColor(a(C.matrix, 0.028))
        ctx.setLineWidth(max(1, s * 0.0006))
        ctx.strokeEllipse(in: CGRect(x: ec.x - r, y: ec.y - r, width: r * 2, height: r * 2))
        ctx.setStrokeColor(a(C.matrix, 0.05))
        ctx.setLineWidth(max(1, s * 0.0008))
        ctx.setLineDash(phase: CGFloat(time * 4), lengths: [s * 0.004, s * 0.010])
        ctx.strokeEllipse(in: CGRect(x: ec.x - r * 1.06, y: ec.y - r * 1.06,
                                      width: r * 2.12, height: r * 2.12))
        ctx.setLineDash(phase: 0, lengths: [])
    }

    /// A recessed memory-dump strip between the two consoles. Bytes count up
    /// continuously over the loop so the seam stays invisible.
    private static func drawHexDump(_ ctx: CGContext, size: CGSize, time: Double,
                                    phase: OverlayPhase) {
        let w = size.width, h = size.height
        let s = min(w, h)
        let pw = min(w * 0.30, s * 0.50)
        let x0 = w * 0.5 - pw * 0.5
        let rect = CGRect(x: x0, y: h * 0.045, width: pw, height: h * 0.092)
        let micro = s * 0.0070
        let kern = micro * 0.10
        let margin = micro * 1.2

        if phase == .geometry {
            ctx.saveGState()
            ctx.setBlendMode(.normal)
            ctx.setFillColor(a(C.black, 0.42))
            ctx.fill(rect)
            ctx.setBlendMode(.screen)
            ctx.setStrokeColor(a(C.matrix, 0.20))
            ctx.setLineWidth(max(1, s * 0.0006))
            ctx.stroke(rect)
            ctx.restoreGState()
            return
        }

        let tx = x0 + margin
        drawLabel(ctx, "MEMDUMP 0x7F3A", at: CGPoint(x: tx, y: rect.maxY - margin - micro * 0.6),
                  size: micro, color: a(C.matrix, 0.50), rightAligned: false, kern: kern)
        let bytesPerRow = 8
        let addrW = textWidth("0000 ", size: micro * 0.9, kern: kern)
        for r in 0..<3 {
            let y = rect.maxY - margin - micro * 2.2 - CGFloat(r) * micro * 1.5
            let addr = 0x7F3A + r * bytesPerRow
            drawLabel(ctx, String(format: "%04X", addr), at: CGPoint(x: tx, y: y),
                      size: micro * 0.9, color: a(C.ice, 0.22), rightAligned: false, kern: kern)
            var hex = ""
            for b in 0..<bytesPerRow {
                let v = (Int((time / loopDuration) * 256.0) + addr + b * 13) % 256
                hex += String(format: "%02X ", v)
            }
            drawLabel(ctx, hex, at: CGPoint(x: tx + addrW, y: y), size: micro * 0.9,
                      color: a(C.matrix, 0.32), rightAligned: false, kern: kern)
        }
    }

    /// A compact `top`-style process list under the telemetry panel, cycling
    /// through a fixed set of rows like the operations console log.
    private static func drawProcessTable(_ ctx: CGContext, size: CGSize, time: Double,
                                         phase: OverlayPhase) {
        let w = size.width, h = size.height
        let s = min(w, h)
        let inset = s * 0.030
        let arm = s * 0.052
        let x = w - inset - arm * 0.38
        let micro = s * 0.0077
        let capY = h * 0.870
        let baseY = capY - micro * 16.2
        let kern = micro * 0.16

        let procs: [(String, String, String, String)] = [
            ("1", "root", "0.0", "kernel_task"),
            ("42", "qtl", "12.4", "sentinel"),
            ("88", "sys", "3.1", "netd"),
            ("102", "ops", "7.7", "tracer"),
            ("113", "vlt", "1.9", "vaultd")
        ]

        if phase == .geometry {
            ctx.setStrokeColor(a(C.blue, 0.10))
            ctx.setLineWidth(max(1, s * 0.0005))
            ctx.move(to: CGPoint(x: x - s * 0.17, y: baseY - micro * 0.4))
            ctx.addLine(to: CGPoint(x: x, y: baseY - micro * 0.4))
            ctx.strokePath()
            return
        }

        drawLabel(ctx, "PROC // SENTRY", at: CGPoint(x: x, y: baseY), size: micro * 0.9,
                  color: a(C.ice, 0.26), rightAligned: true, kern: kern)
        let start = Int(time / 3.0) % procs.count
        for i in 0..<3 {
            let p = procs[(start + i) % procs.count]
            let line = String(format: "%@ %@ %@%% %@", p.0, p.1, p.2, p.3)
            let y = baseY - micro * (1.5 + CGFloat(i) * 1.4)
            drawLabel(ctx, line, at: CGPoint(x: x, y: y), size: micro * 0.9,
                      color: a(i == 1 ? C.matrix : C.blue, 0.30), rightAligned: true, kern: kern)
        }
    }

    /// A brief full-frame CRT glitch: a handful of bright horizontal tear bands
    /// with a slight offset, for 0.12 s every 15 s (an integer divisor of the
    /// loop, so it stays seamless).
    private static func drawGlitch(_ ctx: CGContext, size: CGSize, time: Double) {
        let w = size.width, h = size.height
        let s = min(w, h)
        let cycle = time.truncatingRemainder(dividingBy: 15.0)
        guard cycle < 0.12 else { return }
        let env = CGFloat(1.0 - cycle / 0.12)
        let gi = Int(time / 15.0)

        ctx.saveGState()
        ctx.setBlendMode(.screen)
        for i in 0..<4 {
            let fy = rand(i * 7 + 1 + gi)
            let y = CGFloat(fy) * h
            let bh = s * (0.002 + 0.006 * rand(i * 13 + gi))
            ctx.setFillColor(a(C.ice, CGFloat(0.06 + 0.10 * rand(i * 17 + gi)) * env))
            ctx.fill(CGRect(x: 0, y: y, width: w, height: bh))
            ctx.setFillColor(a(C.matrix, 0.045 * env))
            ctx.fill(CGRect(x: s * 0.004, y: y - bh * 2.2, width: w, height: bh * 0.5))
        }
        ctx.restoreGState()
    }

    // MARK: - Radar dome

    private static func drawRadar(_ ctx: CGContext, size: CGSize, center: CGPoint,
                                  time: Double, detail: Double) {
        let w = size.width, h = size.height
        let s = min(w, h)
        let radius = s * 0.362

        // Range rings.
        for i in 1...3 {
            let r = radius * CGFloat(i) / 3.0
            ctx.setStrokeColor(a(C.blue, 0.045))
            ctx.setLineWidth(max(1, h * 0.0006))
            ctx.strokeEllipse(in: CGRect(x: center.x - r, y: center.y - r,
                                         width: r * 2, height: r * 2))
        }

        // Acquisition ring.
        ctx.setStrokeColor(a(C.cyan, 0.105))
        ctx.setLineWidth(max(1, h * 0.0009))
        ctx.setLineDash(phase: CGFloat(time * 10), lengths: [s * 0.005, s * 0.014])
        ctx.strokeEllipse(in: CGRect(x: center.x - radius, y: center.y - radius,
                                     width: radius * 2, height: radius * 2))
        ctx.setLineDash(phase: 0, lengths: [])

        // Latitude ellipses for a shallow holographic dome.
        for k in stride(from: -0.72, through: 0.72, by: 0.24) {
            let kk = CGFloat(k)
            let rx = radius * CGFloat(sqrt(max(0.0, 1.0 - k * k)))
            let ry = radius * 0.085 * (1.0 - abs(kk) * 0.45)
            let y = center.y + kk * radius
            ctx.setStrokeColor(a(C.blue, 0.035))
            ctx.setLineWidth(max(1, h * 0.0005))
            ctx.strokeEllipse(in: CGRect(x: center.x - rx, y: y - ry,
                                         width: rx * 2, height: ry * 2))
        }

        // Meridian curves.
        for j in -4...4 {
            let off = CGFloat(j) * radius * 0.17
            let path = CGMutablePath()
            path.move(to: CGPoint(x: center.x, y: center.y + radius))
            path.addQuadCurve(to: CGPoint(x: center.x, y: center.y - radius),
                              control: CGPoint(x: center.x + off * 2.0, y: center.y))
            ctx.addPath(path)
            ctx.setStrokeColor(a(C.blue, 0.028))
            ctx.setLineWidth(max(1, h * 0.0005))
            ctx.strokePath()
        }

        // Bearing ticks.
        let ticks = detail > 0.5 ? 120 : 60
        for i in 0..<ticks {
            let angle = Double(i) / Double(ticks) * Double.pi * 2
            let major = i % (ticks / 12) == 0
            let inner = radius * (major ? 1.015 : 1.035)
            let outer = radius * (major ? 1.075 : 1.052)
            ctx.setStrokeColor(a(major ? C.cyan : C.blue, major ? 0.24 : 0.08))
            ctx.setLineWidth(max(1, h * (major ? 0.0013 : 0.0006)))
            ctx.move(to: CGPoint(x: center.x + CGFloat(cos(angle)) * inner,
                                 y: center.y + CGFloat(sin(angle)) * inner))
            ctx.addLine(to: CGPoint(x: center.x + CGFloat(cos(angle)) * outer,
                                    y: center.y + CGFloat(sin(angle)) * outer))
            ctx.strokePath()
        }

        // Rotating sweep.
        let sweep = -time * omega * 2.0 + Double.pi * 0.55
        let wedge = 0.70
        ctx.setFillColor(a(C.cyan, 0.030))
        ctx.beginPath()
        ctx.move(to: center)
        ctx.addArc(center: center, radius: radius,
                   startAngle: CGFloat(sweep - wedge), endAngle: CGFloat(sweep),
                   clockwise: false)
        ctx.closePath()
        ctx.fillPath()

        ctx.setStrokeColor(a(C.cyan, 0.32))
        ctx.setLineWidth(max(1.5, h * 0.0015))
        ctx.move(to: center)
        ctx.addLine(to: CGPoint(x: center.x + CGFloat(cos(sweep)) * radius,
                                y: center.y + CGFloat(sin(sweep)) * radius))
        ctx.strokePath()

        // Contacts, only revealed as the sweep passes.
        let contacts: [(Double, CGFloat, CGColor)] = [
            (1.72, 0.80, C.red),
            (3.80, 0.64, C.amber),
            (5.35, 0.90, C.ice)
        ]
        for (angle, rf, color) in contacts {
            let delta = abs(atan2(sin(sweep - angle), cos(sweep - angle)))
            let lit = max(0.0, 1.0 - delta / 0.55)
            guard lit > 0.02 else { continue }
            let r = radius * rf
            let p = CGPoint(x: center.x + CGFloat(cos(angle)) * r,
                            y: center.y + CGFloat(sin(angle)) * r * 0.92)
            let dot = s * 0.0026
            ctx.setFillColor(a(color, CGFloat(0.35 + 0.55 * lit)))
            ctx.fillEllipse(in: CGRect(x: p.x - dot, y: p.y - dot,
                                       width: dot * 2, height: dot * 2))
            ctx.setStrokeColor(a(color, CGFloat(0.35 * lit)))
            ctx.setLineWidth(max(1, h * 0.0009))
            ctx.strokeEllipse(in: CGRect(x: p.x - dot * 4, y: p.y - dot * 4,
                                         width: dot * 8, height: dot * 8))
        }

        // Target lock on the primary red contact.
        let lockAngle = 1.72
        let lockR = radius * 0.80
        let lock = CGPoint(x: center.x + CGFloat(cos(lockAngle)) * lockR,
                           y: center.y + CGFloat(sin(lockAngle)) * lockR * 0.92)
        let lockSize = s * 0.021
        let lockPulse = 0.32 + 0.18 * CGFloat((sin(time * omega * 2.0) + 1.0) * 0.5)
        ctx.setStrokeColor(a(C.red, lockPulse))
        ctx.setLineWidth(max(1, h * 0.0011))
        for sx in [CGFloat(-1), CGFloat(1)] {
            for sy in [CGFloat(-1), CGFloat(1)] {
                let cx = lock.x + sx * lockSize
                let cy = lock.y + sy * lockSize
                ctx.move(to: CGPoint(x: cx - sx * lockSize * 0.55, y: cy))
                ctx.addLine(to: CGPoint(x: cx, y: cy))
                ctx.addLine(to: CGPoint(x: cx, y: cy - sy * lockSize * 0.55))
                ctx.strokePath()
            }
        }
        ctx.setStrokeColor(a(C.red, lockPulse * 0.5))
        ctx.setLineWidth(max(1, h * 0.0007))
        ctx.move(to: CGPoint(x: lock.x - lockSize * 0.5, y: lock.y))
        ctx.addLine(to: CGPoint(x: lock.x + lockSize * 0.5, y: lock.y))
        ctx.move(to: CGPoint(x: lock.x, y: lock.y - lockSize * 0.5))
        ctx.addLine(to: CGPoint(x: lock.x, y: lock.y + lockSize * 0.5))
        ctx.strokePath()
    }

    // MARK: - Core beam

    private static func drawBeam(_ ctx: CGContext, size: CGSize, center: CGPoint,
                                 irisR: CGFloat, time: Double) {
        let w = size.width, h = size.height
        let top = center.y - irisR * 0.30
        let bottom = h * 0.175
        let halfBottom = w * 0.055
        let halfTop = w * 0.018

        let path = CGMutablePath()
        path.move(to: CGPoint(x: center.x - halfBottom, y: bottom))
        path.addLine(to: CGPoint(x: center.x + halfBottom, y: bottom))
        path.addLine(to: CGPoint(x: center.x + halfTop, y: top))
        path.addLine(to: CGPoint(x: center.x - halfTop, y: top))
        path.closeSubpath()

        ctx.saveGState()
        ctx.addPath(path)
        ctx.clip()
        let colors = [
            a(C.cyan, 0.10),
            a(C.blue, 0.05),
            a(C.black, 0.0)
        ] as CFArray
        if let g = CGGradient(colorsSpace: CGColorSpaceCreateDeviceRGB(), colors: colors,
                              locations: [0.0, 0.45, 1.0]) {
            ctx.drawLinearGradient(g, start: CGPoint(x: center.x, y: bottom),
                                   end: CGPoint(x: center.x, y: top), options: [])
        }
        // Energy bands rising toward the vault.
        for i in 0..<4 {
            let p = ((time / 7.5 + Double(i) / 4.0).truncatingRemainder(dividingBy: 1.0))
            let y = bottom + CGFloat(p) * (top - bottom)
            let alpha = CGFloat(0.05 + 0.10 * (1.0 - p))
            ctx.setStrokeColor(a(C.ice, alpha))
            ctx.setLineWidth(max(1, h * 0.0014))
            ctx.move(to: CGPoint(x: center.x - halfBottom, y: y))
            ctx.addLine(to: CGPoint(x: center.x + halfBottom, y: y))
            ctx.strokePath()
        }
        ctx.restoreGState()

        // Platform impact glow.
        let glow = [a(C.cyan, 0.20), a(C.blue, 0.05), a(C.black, 0.0)] as CFArray
        if let g = CGGradient(colorsSpace: CGColorSpaceCreateDeviceRGB(), colors: glow,
                              locations: [0.0, 0.45, 1.0]) {
            ctx.drawRadialGradient(g,
                                   startCenter: CGPoint(x: center.x, y: bottom),
                                   startRadius: 0,
                                   endCenter: CGPoint(x: center.x, y: bottom),
                                   endRadius: w * 0.12, options: [])
        }
    }

    // MARK: - Energy rings

    private static func drawEnergyRings(_ ctx: CGContext, size: CGSize, center: CGPoint,
                                        irisR: CGFloat, time: Double) {
        let h = size.height
        let s = min(size.width, size.height)
        struct Ring {
            let factor: CGFloat
            let speed: Double
            let span: Double
            let phase: Double
            let color: CGColor
            let width: CGFloat
        }
        let rings: [Ring] = [
            Ring(factor: 1.045, speed: 1.0, span: 0.95, phase: 0.0, color: C.cyan, width: 0.0022),
            Ring(factor: 0.985, speed: -2.0, span: 0.55, phase: 1.7, color: C.ice, width: 0.0014),
            Ring(factor: 1.105, speed: -1.0, span: 1.35, phase: 3.4, color: C.violet, width: 0.0018)
        ]

        for ring in rings {
            let r = irisR * ring.factor
            let start = time * omega * ring.speed + ring.phase
            let end = start + ring.span
            for (mult, alpha) in [(5.0, 0.045), (2.5, 0.11), (1.0, 0.55)] {
                ctx.setStrokeColor(a(ring.color, CGFloat(alpha)))
                ctx.setLineWidth(max(1, s * ring.width * CGFloat(mult)))
                ctx.addArc(center: center, radius: r,
                           startAngle: CGFloat(start), endAngle: CGFloat(end),
                           clockwise: false)
                ctx.strokePath()
            }
            // Bright head.
            let head = CGPoint(x: center.x + CGFloat(cos(end)) * r,
                               y: center.y + CGFloat(sin(end)) * r)
            let dot = s * 0.0042
            ctx.setFillColor(a(C.ice, 0.75))
            ctx.fillEllipse(in: CGRect(x: head.x - dot, y: head.y - dot,
                                       width: dot * 2, height: dot * 2))
            ctx.setFillColor(a(ring.color, 0.22))
            ctx.fillEllipse(in: CGRect(x: head.x - dot * 3, y: head.y - dot * 3,
                                       width: dot * 6, height: dot * 6))
        }

        // Slow counter-rotating dashed containment ring.
        ctx.setStrokeColor(a(C.blue, 0.10))
        ctx.setLineWidth(max(1, h * 0.0007))
        ctx.setLineDash(phase: CGFloat(time * 20), lengths: [s * 0.003, s * 0.010])
        let r = irisR * 1.28
        ctx.strokeEllipse(in: CGRect(x: center.x - r, y: center.y - r,
                                     width: r * 2, height: r * 2))
        ctx.setLineDash(phase: 0, lengths: [])
    }

    // MARK: - Core

    private static func drawCore(_ ctx: CGContext, size: CGSize, center: CGPoint, time: Double) {
        let w = size.width, h = size.height
        let s = min(w, h)
        let pulse = CGFloat((sin(time * omega * 4.0) + 1.0) * 0.5)
        let coreR = s * 0.060

        // Bloom.
        let bloom = [
            a(C.blue, 0.22),
            a(C.violet, 0.10),
            a(C.violet, 0.0)
        ] as CFArray
        if let g = CGGradient(colorsSpace: CGColorSpaceCreateDeviceRGB(), colors: bloom,
                              locations: [0.0, 0.38, 1.0]) {
            ctx.drawRadialGradient(g, startCenter: center, startRadius: 0,
                                   endCenter: center, endRadius: coreR * 5.0, options: [])
        }

        // Rotating targeting reticle.
        let reticleR = coreR * 1.62
        let reticleRot = time * omega * 1.0
        for i in 0..<4 {
            let ang = reticleRot + Double(i) * Double.pi * 0.5
            let span = 0.16
            ctx.setStrokeColor(a(C.cyan, 0.30))
            ctx.setLineWidth(max(1, h * 0.0011))
            ctx.addArc(center: center, radius: reticleR,
                       startAngle: CGFloat(ang - span), endAngle: CGFloat(ang + span),
                       clockwise: false)
            ctx.strokePath()
            let tip = CGPoint(x: center.x + CGFloat(cos(ang)) * reticleR,
                              y: center.y + CGFloat(sin(ang)) * reticleR)
            let dot = coreR * 0.035
            ctx.setFillColor(a(C.ice, 0.45))
            ctx.fillEllipse(in: CGRect(x: tip.x - dot, y: tip.y - dot,
                                       width: dot * 2, height: dot * 2))
        }

        // Integrity ring with a moving scan arc.
        let integrityR = coreR * 2.05
        ctx.setStrokeColor(a(C.blue, 0.18))
        ctx.setLineWidth(max(1, h * 0.0008))
        ctx.strokeEllipse(in: CGRect(x: center.x - integrityR, y: center.y - integrityR,
                                     width: integrityR * 2, height: integrityR * 2))
        let arcStart = -Double.pi * 0.5 + time * omega * 1.0
        let arcSpan = 1.15 + 0.30 * sin(time * omega * 2.0)
        for (mult, alpha) in [(4.0, 0.05), (2.0, 0.14), (1.0, 0.55)] {
            ctx.setStrokeColor(a(C.cyan, CGFloat(alpha)))
            ctx.setLineWidth(max(1, h * 0.0014 * CGFloat(mult)))
            ctx.addArc(center: center, radius: integrityR,
                       startAngle: CGFloat(arcStart), endAngle: CGFloat(arcStart + arcSpan),
                       clockwise: false)
            ctx.strokePath()
        }

        // Authentication pulses expanding from the core (6 s period).
        for i in 0..<2 {
            let p = ((time / 6.0 + Double(i) * 0.5).truncatingRemainder(dividingBy: 1.0))
            let r = coreR * (1.55 + CGFloat(p) * 2.40)
            let fade = pow(1.0 - p, 2.0)
            ctx.setStrokeColor(a(C.cyan, CGFloat(0.20 * fade)))
            ctx.setLineWidth(max(1, h * 0.0010))
            ctx.strokeEllipse(in: CGRect(x: center.x - r, y: center.y - r,
                                         width: r * 2, height: r * 2))
        }

        // Hexagonal plate.
        let hexR = coreR * 1.16
        let hexRot = time * omega * 1.0
        let hex = CGMutablePath()
        for i in 0..<6 {
            let ang = hexRot + Double(i) * Double.pi / 3.0 + Double.pi / 6.0
            let p = CGPoint(x: center.x + CGFloat(cos(ang)) * hexR,
                            y: center.y + CGFloat(sin(ang)) * hexR)
            if i == 0 { hex.move(to: p) } else { hex.addLine(to: p) }
        }
        hex.closeSubpath()
        ctx.setFillColor(a(C.black, 0.92))
        ctx.addPath(hex)
        ctx.fillPath()
        for (width, alpha) in [(0.008, 0.07), (0.003, 0.20), (0.0014, 0.70)] {
            ctx.setStrokeColor(a(C.cyan, CGFloat(alpha)))
            ctx.setLineWidth(max(1, h * CGFloat(width)))
            ctx.addPath(hex)
            ctx.strokePath()
        }

        // Inner violet trace.
        let innerR = hexR * 0.78
        let inner = CGMutablePath()
        for i in 0..<6 {
            let ang = -hexRot * 2.0 + Double(i) * Double.pi / 3.0 + Double.pi / 6.0
            let p = CGPoint(x: center.x + CGFloat(cos(ang)) * innerR,
                            y: center.y + CGFloat(sin(ang)) * innerR)
            if i == 0 { inner.move(to: p) } else { inner.addLine(to: p) }
        }
        inner.closeSubpath()
        ctx.setStrokeColor(a(C.violet, 0.52 + 0.16 * pulse))
        ctx.setLineWidth(max(1, h * 0.0013))
        ctx.addPath(inner)
        ctx.strokePath()

        // Violet outer hex trace.
        let outerHex = CGMutablePath()
        let outerHexR = hexR * 1.34
        for i in 0..<6 {
            let ang = hexRot * 1.0 + Double(i) * Double.pi / 3.0 + Double.pi / 6.0
            let p = CGPoint(x: center.x + CGFloat(cos(ang)) * outerHexR,
                            y: center.y + CGFloat(sin(ang)) * outerHexR)
            if i == 0 { outerHex.move(to: p) } else { outerHex.addLine(to: p) }
        }
        outerHex.closeSubpath()
        ctx.setStrokeColor(a(C.violet, 0.30))
        ctx.setLineWidth(max(1, h * 0.0010))
        ctx.setLineDash(phase: CGFloat(time * 8), lengths: [h * 0.004, h * 0.006])
        ctx.addPath(outerHex)
        ctx.strokePath()
        ctx.setLineDash(phase: 0, lengths: [])

        // Segmented authorization ring.
        let ringR = coreR * 1.62
        let segments = 36
        for i in 0..<segments {
            let step = Double.pi * 2 / Double(segments)
            let start = time * omega * 1.0 + Double(i) * step
            let end = start + step * 0.62
            let alert = i % 9 == 4
            ctx.setStrokeColor(a(alert ? C.red : C.cyan, alert ? 0.35 : 0.14))
            ctx.setLineWidth(max(1, h * 0.0011))
            ctx.addArc(center: center, radius: ringR,
                       startAngle: CGFloat(start), endAngle: CGFloat(end),
                       clockwise: false)
            ctx.strokePath()
        }

        drawPadlock(ctx, center: center, coreR: coreR, pulse: pulse, size: size)
    }

    private static func drawPadlock(_ ctx: CGContext, center: CGPoint, coreR: CGFloat,
                                    pulse: CGFloat, size: CGSize) {
        let s = min(size.width, size.height)
        let bodyW = coreR * 0.92
        let bodyH = coreR * 0.76
        let body = CGRect(x: center.x - bodyW * 0.5,
                          y: center.y - bodyH * 0.62,
                          width: bodyW, height: bodyH)
        let corner = bodyW * 0.13

        // Shackle.
        let shackleR = bodyW * 0.31
        ctx.setStrokeColor(a(C.ice, 0.88))
        ctx.setLineWidth(max(1.5, coreR * 0.11))
        ctx.addArc(center: CGPoint(x: center.x, y: body.maxY - coreR * 0.02),
                   radius: shackleR,
                   startAngle: CGFloat(Double.pi * 0.02),
                   endAngle: CGFloat(Double.pi * 0.98),
                   clockwise: false)
        ctx.strokePath()

        // Body.
        let bodyPath = CGPath(roundedRect: body, cornerWidth: corner,
                              cornerHeight: corner, transform: nil)
        ctx.setFillColor(a(C.black, 0.96))
        ctx.addPath(bodyPath)
        ctx.fillPath()
        for (width, alpha) in [(0.008, 0.10), (0.0035, 0.30), (0.0015, 0.90)] {
            ctx.setStrokeColor(a(C.cyan, CGFloat(alpha)))
            ctx.setLineWidth(max(1, coreR * CGFloat(width)))
            ctx.addPath(bodyPath)
            ctx.strokePath()
        }

        // Keyhole.
        let keyR = coreR * 0.115
        let keyCenter = CGPoint(x: center.x, y: body.midY + coreR * 0.055)
        ctx.setFillColor(a(C.ice, 0.95))
        ctx.fillEllipse(in: CGRect(x: keyCenter.x - keyR, y: keyCenter.y - keyR,
                                   width: keyR * 2, height: keyR * 2))
        let slot = CGMutablePath()
        slot.move(to: CGPoint(x: keyCenter.x - keyR * 0.45, y: keyCenter.y - keyR * 0.15))
        slot.addLine(to: CGPoint(x: keyCenter.x + keyR * 0.45, y: keyCenter.y - keyR * 0.15))
        slot.addLine(to: CGPoint(x: keyCenter.x + keyR * 0.9, y: body.minY + bodyH * 0.20))
        slot.addLine(to: CGPoint(x: keyCenter.x - keyR * 0.9, y: body.minY + bodyH * 0.20))
        slot.closeSubpath()
        ctx.addPath(slot)
        ctx.fillPath()

        // Pulse halo.
        ctx.setStrokeColor(a(C.cyan, 0.18 * pulse))
        ctx.setLineWidth(max(1, s * 0.0012))
        ctx.strokeEllipse(in: CGRect(x: center.x - coreR * 1.95,
                                     y: center.y - coreR * 1.95,
                                     width: coreR * 3.9, height: coreR * 3.9))
    }

    // MARK: - Orbital traffic

    private static func drawOrbitalTraffic(_ ctx: CGContext, size: CGSize, center: CGPoint,
                                           irisR: CGFloat, time: Double) {
        let s = min(size.width, size.height)
        let h = size.height
        let phase = time / loopDuration

        for i in 0..<5 {
            let radius = irisR * (1.11 + CGFloat(i % 2) * 0.07)
            let speed = Double(1 + i % 3)
            let direction: Double = i % 2 == 0 ? 1 : -1
            let angle = (phase * speed * direction + Double(i) * 0.77) * Double.pi * 2
            let p = CGPoint(x: center.x + CGFloat(cos(angle)) * radius,
                            y: center.y + CGFloat(sin(angle)) * radius * 0.94)
            let color = i % 4 == 3 ? C.amber : C.ice
            let dot = s * 0.0032
            // Trail along the orbit.
            for k in 0..<5 {
                let f = CGFloat(k) / 5.0
                let ta = angle - direction * Double(f) * 0.10
                let tp = CGPoint(x: center.x + CGFloat(cos(ta)) * radius,
                                 y: center.y + CGFloat(sin(ta)) * radius * 0.94)
                ctx.setFillColor(a(color, 0.02 + 0.10 * (1.0 - f)))
                let tr = dot * (1.0 - f * 0.5)
                ctx.fillEllipse(in: CGRect(x: tp.x - tr, y: tp.y - tr,
                                           width: tr * 2, height: tr * 2))
            }
            ctx.setFillColor(a(color, 0.9))
            ctx.fillEllipse(in: CGRect(x: p.x - dot, y: p.y - dot,
                                       width: dot * 2, height: dot * 2))
            ctx.setFillColor(a(color, 0.18))
            ctx.fillEllipse(in: CGRect(x: p.x - dot * 3, y: p.y - dot * 3,
                                       width: dot * 6, height: dot * 6))
            _ = h
        }
    }

    // MARK: - Pylon traffic

    private static func drawPylonTraffic(_ ctx: CGContext, size: CGSize, time: Double) {
        let w = size.width, h = size.height
        let s = min(w, h)
        let phase = time / loopDuration
        let strips: [(CGFloat, Double, CGColor)] = [
            (w * 0.110, 1.0, C.cyan),
            (w * 0.890, -1.0, C.amber),
            (w * 0.244, 2.0, C.cyan),
            (w * 0.756, -2.0, C.cyan)
        ]
        for (index, strip) in strips.enumerated() {
            let x = strip.0
            let direction = strip.1
            let color = strip.2
            for packet in 0..<2 {
                let p = ((phase * abs(direction) + Double(packet) * 0.5 + Double(index) * 0.21)
                    .truncatingRemainder(dividingBy: 1.0))
                let y = h * 0.24 + CGFloat(p) * h * 0.40
                let trail = s * 0.020
                for k in 0..<5 {
                    let f = CGFloat(k) / 5.0
                    ctx.setStrokeColor(a(color, 0.02 + 0.10 * f))
                    ctx.setLineWidth(max(1, h * 0.0009))
                    let y0 = y - direction * Double(trail) * Double(1.0 - f)
                    let y1 = y - direction * Double(trail) * Double(1.0 - (f + 0.2))
                    ctx.move(to: CGPoint(x: x, y: CGFloat(y0)))
                    ctx.addLine(to: CGPoint(x: x, y: CGFloat(y1)))
                    ctx.strokePath()
                }
                let dot = s * 0.0018
                ctx.setFillColor(a(color, 0.85))
                ctx.fillEllipse(in: CGRect(x: x - dot, y: y - dot,
                                           width: dot * 2, height: dot * 2))
            }
        }
    }

    // MARK: - Particles

    private static func drawParticles(_ ctx: CGContext, size: CGSize, time: Double) {
        let w = size.width, h = size.height
        let s = min(w, h)
        let phase = time / loopDuration
        for i in 0..<130 {
            let seed = Double(i) * 1.618_033_988_749_895
            let bx = (sin(seed * 12.9898) * 43758.5453).truncatingRemainder(dividingBy: 1.0)
            let by = (sin(seed * 78.233) * 12345.6789).truncatingRemainder(dividingBy: 1.0)
            let baseX = CGFloat(abs(bx))
            let baseY = CGFloat(abs(by))
            let speed = 0.006 + Double(i % 7) * 0.002
            let y = CGFloat((Double(baseY) + phase * speed)
                .truncatingRemainder(dividingBy: 1.0)) * h
            let x = baseX * w + CGFloat(sin(time * omega + seed)) * s * 0.006
            let r = s * (0.0005 + CGFloat(i % 4) * 0.00035)
            let alpha = CGFloat(0.04 + 0.09 * ((sin(time * omega * 2.0 + seed) + 1.0) * 0.5))
            ctx.setFillColor(a(i % 9 == 0 ? C.amber : C.ice, alpha))
            ctx.fillEllipse(in: CGRect(x: x - r, y: y - r, width: r * 2, height: r * 2))
        }
    }

    // MARK: - Threat pings

    private static func drawThreatPings(_ ctx: CGContext, size: CGSize, center: CGPoint,
                                        irisR: CGFloat, time: Double) {
        let w = size.width, h = size.height
        let s = min(w, h)
        let pings: [(CGFloat, CGFloat, Double, CGColor)] = [
            (center.x - irisR * 1.24, center.y + irisR * 0.58, 0.00, C.red),
            (center.x + irisR * 1.32, center.y - irisR * 0.42, 0.37, C.red),
            (w * 0.205, h * 0.245, 0.68, C.amber),
            (w * 0.795, h * 0.205, 0.84, C.amber)
        ]
        for (x, y, offset, color) in pings {
            let cycle = ((time / 10.0 + offset).truncatingRemainder(dividingBy: 1.0))
            let fade = pow(1.0 - cycle, 2.0)
            let r = s * 0.005 + s * 0.030 * CGFloat(cycle)
            ctx.setStrokeColor(a(color, CGFloat(0.42 * fade)))
            ctx.setLineWidth(max(1, h * 0.0012))
            ctx.strokeEllipse(in: CGRect(x: x - r, y: y - r, width: r * 2, height: r * 2))
            let dot = s * 0.0024
            ctx.setFillColor(a(color, CGFloat(0.55 + 0.35 * fade)))
            ctx.fillEllipse(in: CGRect(x: x - dot, y: y - dot,
                                       width: dot * 2, height: dot * 2))
            ctx.setStrokeColor(a(color, CGFloat(0.28 * fade)))
            ctx.setLineWidth(max(1, h * 0.0007))
            let arm = s * 0.009
            ctx.move(to: CGPoint(x: x - arm, y: y))
            ctx.addLine(to: CGPoint(x: x + arm, y: y))
            ctx.move(to: CGPoint(x: x, y: y - arm))
            ctx.addLine(to: CGPoint(x: x, y: y + arm))
            ctx.strokePath()
        }
    }

    // MARK: - Scan sweep

    private static func drawScanSweep(_ ctx: CGContext, size: CGSize, time: Double) {
        let w = size.width, h = size.height
        let p = (time / 7.5).truncatingRemainder(dividingBy: 1.0)
        let y = h * (1.0 - CGFloat(p))
        for (width, alpha) in [(h * 0.022, 0.007), (h * 0.006, 0.020), (max(1, h * 0.0011), 0.080)] {
            ctx.setStrokeColor(a(C.cyan, CGFloat(alpha)))
            ctx.setLineWidth(width)
            ctx.move(to: CGPoint(x: 0, y: y))
            ctx.addLine(to: CGPoint(x: w, y: y))
            ctx.strokePath()
        }
    }

    // MARK: - Chrono module

    private struct Chrono {
        let hourMinute: String
        let seconds: String
        let date: String
        let zone: String
        let hash: String
        let second: Int
        let hour: Int
        let minute: Int
        let secondsOfDay: Int
        let fraction: Double
        let colonAlpha: CGFloat
    }

    private static let utcCalendar: Calendar = {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = TimeZone(identifier: "UTC") ?? TimeZone(secondsFromGMT: 0)!
        return calendar
    }()

    private static let weekdayNames = ["SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT"]

    /// Live layer: the real local clock. Loop maker / preview: a fixed UTC
    /// reference advancing with the loop, so renders stay deterministic.
    private static func chrono(_ wallClock: Date?, time: Double) -> Chrono {
        let synthetic = wallClock == nil
        let date = wallClock ?? Date(timeIntervalSince1970: 1_792_471_020 + time)
        let calendar = synthetic ? utcCalendar : Calendar.current
        let parts = calendar.dateComponents([.year, .month, .day, .hour, .minute, .second, .weekday],
                                            from: date)
        let fraction = date.timeIntervalSince1970.truncatingRemainder(dividingBy: 1)
        let offset = calendar.timeZone.secondsFromGMT(for: date)
        let absOffset = abs(offset)
        let zone = String(format: "UTC%@%02d:%02d", offset < 0 ? "-" : "+",
                          absOffset / 3600, (absOffset % 3600) / 60)
        let weekday = weekdayNames[max(0, min(6, (parts.weekday ?? 1) - 1))]
        let second = parts.second ?? 0
        let hour = parts.hour ?? 0
        let minute = parts.minute ?? 0
        return Chrono(
            hourMinute: String(format: "%02d:%02d", hour, minute),
            seconds: String(format: "%02d", second),
            date: String(format: "%04d.%02d.%02d  %@",
                         parts.year ?? 2026, parts.month ?? 1, parts.day ?? 1, weekday),
            zone: zone,
            hash: String(format: "%08X", UInt32(truncatingIfNeeded: Int(date.timeIntervalSince1970))),
            second: second,
            hour: hour,
            minute: minute,
            secondsOfDay: hour * 3600 + minute * 60 + second,
            fraction: fraction,
            colonAlpha: fraction < 0.52 ? 1.0 : 0.18
        )
    }

    private static func drawChrono(_ ctx: CGContext, size: CGSize, time: Double,
                                   wallClock: Date?, phase: OverlayPhase) {
        let w = size.width, h = size.height
        let s = min(w, h)
        let inset = s * 0.030
        let arm = s * 0.052
        let x = inset + arm * 0.38
        let clockSize = s * 0.038
        let micro = s * 0.0077
        let capY = h * 0.870
        let timeY = capY - clockSize * 1.28
        let dateY = timeY - micro * 2.25
        let hashY = dateY - micro * 1.72
        let barY = hashY - micro * 2.20
        let barW = min(s * 0.196, w * 0.205)
        let reading = chrono(wallClock, time: time)
        let valueAlpha: CGFloat = 0.62

        ctx.saveGState()

        if phase == .geometry {
            let lamp = s * 0.0024
            let lampPulse = 0.55 + 0.35 * CGFloat((sin(time * omega * 2.0) + 1.0) * 0.5)
            ctx.setFillColor(a(C.cyan, lampPulse))
            ctx.fillEllipse(in: CGRect(x: x - micro * 1.65 - lamp, y: capY + micro * 0.30 - lamp,
                                       width: lamp * 2, height: lamp * 2))

            // Vertical spine with segment ticks.
            let spineX = x - micro * 0.95
            let spineTop = capY + micro * 0.15
            let spineBottom = barY - micro * 0.55
            ctx.setStrokeColor(a(C.cyan, 0.22))
            ctx.setLineWidth(max(1, s * 0.0007))
            ctx.move(to: CGPoint(x: spineX, y: spineBottom))
            ctx.addLine(to: CGPoint(x: spineX, y: spineTop))
            ctx.strokePath()
            for i in 0..<12 {
                let y = spineBottom + (spineTop - spineBottom) * CGFloat(i) / 11.0
                ctx.setStrokeColor(a(C.cyan, i % 3 == 0 ? 0.4 : 0.16))
                ctx.setLineWidth(max(1, s * 0.0006))
                ctx.move(to: CGPoint(x: spineX, y: y))
                ctx.addLine(to: CGPoint(x: spineX - (i % 3 == 0 ? micro * 1.1 : micro * 0.58), y: y))
                ctx.strokePath()
            }

            // Terminal block cursor riding just past the seconds.
            let cell = textWidth("0", size: clockSize, kern: clockSize * 0.075)
            let cursorOn = reading.fraction < 0.5
            ctx.setFillColor(a(C.ice, cursorOn ? 0.22 : 0.04))
            ctx.fill(CGRect(x: x + cell * 8.14, y: timeY - clockSize * 0.015,
                            width: cell * 0.44, height: clockSize * 0.62))

            // Divider.
            ctx.setStrokeColor(a(C.cyan, 0.16))
            ctx.setLineWidth(max(1, s * 0.0006))
            ctx.move(to: CGPoint(x: x, y: timeY - clockSize * 0.56))
            ctx.addLine(to: CGPoint(x: x + barW, y: timeY - clockSize * 0.56))
            ctx.strokePath()

            // Sixty-tick seconds rail.
            let ticks = 60
            let tickW = barW / CGFloat(ticks)
            let tickH = s * 0.0046
            for i in 0..<ticks {
                let filled = i < reading.second
                let live = i == reading.second
                let alpha: CGFloat = live ? 0.88 : (filled ? 0.42 : 0.10)
                let tx = x + CGFloat(i) * tickW
                let height = live ? tickH * 1.35 : tickH
                ctx.setFillColor(a(live ? C.ice : C.cyan, alpha))
                ctx.fill(CGRect(x: tx, y: barY, width: max(1, tickW * 0.62), height: height))
            }
            let headX = x + CGFloat(Double(reading.second) + reading.fraction) / 60.0 * barW
            let head = s * 0.0016
            ctx.setFillColor(a(C.ice, 0.9))
            ctx.fillEllipse(in: CGRect(x: headX - head, y: barY + tickH * 0.5 - head,
                                       width: head * 2, height: head * 2))
        } else {
            let caption = "LOCAL TIME // \(reading.zone)"
            drawLabel(ctx, caption, at: CGPoint(x: x, y: capY), size: micro,
                      color: a(C.ice, 0.34), rightAligned: false, kern: micro * 0.22)

            // Big monospaced time with a neon stroke glow.
            let clockKern = clockSize * 0.075
            let cell = textWidth("0", size: clockSize, kern: clockKern)
            let hour = String(reading.hourMinute.prefix(2))
            let minute = String(reading.hourMinute.suffix(2))
            drawGlowLabel(ctx, hour, at: CGPoint(x: x, y: timeY), size: clockSize,
                          color: a(C.ice, valueAlpha), kern: clockKern, glow: 0.9)
            drawLabel(ctx, ":", at: CGPoint(x: x + cell * 2, y: timeY), size: clockSize,
                      color: a(C.cyan, valueAlpha * reading.colonAlpha),
                      rightAligned: false, kern: clockKern, glow: 0.55)
            drawGlowLabel(ctx, minute, at: CGPoint(x: x + cell * 3, y: timeY), size: clockSize,
                          color: a(C.ice, valueAlpha), kern: clockKern, glow: 0.9)
            drawLabel(ctx, ":", at: CGPoint(x: x + cell * 5, y: timeY), size: clockSize,
                      color: a(C.cyan, valueAlpha * reading.colonAlpha),
                      rightAligned: false, kern: clockKern, glow: 0.55)
            drawGlowLabel(ctx, reading.seconds, at: CGPoint(x: x + cell * 6, y: timeY),
                          size: clockSize, color: a(C.cyan, valueAlpha), kern: clockKern, glow: 0.9)

            drawLabel(ctx, reading.date, at: CGPoint(x: x, y: dateY), size: micro,
                      color: a(C.ice, 0.34), rightAligned: false, kern: micro * 0.2)
            drawLabel(ctx, "0x\(reading.hash) // SESSION SECURE", at: CGPoint(x: x, y: hashY),
                      size: micro, color: a(C.cyan, 0.30), rightAligned: false, kern: micro * 0.2)

            let tickH = s * 0.0046
            drawLabel(ctx, "T+\(String(format: "%02d", reading.second))s", at: CGPoint(x: x + barW, y: barY + tickH * 1.9),
                      size: micro * 0.85, color: a(C.cyan, 0.32), rightAligned: true, kern: micro * 0.16)
        }

        ctx.restoreGState()
    }

    // MARK: - Threat telemetry

    private static func drawTelemetry(_ ctx: CGContext, size: CGSize, time: Double,
                                      phase: OverlayPhase) {
        let w = size.width, h = size.height
        let s = min(w, h)
        let inset = s * 0.030
        let arm = s * 0.052
        let x = w - inset - arm * 0.38
        let micro = s * 0.0077
        let capY = h * 0.870
        let span = s * 0.170

        let probes = 1284 + Int(38.0 * (0.5 + 0.5 * sin(time * omega * 3.0)))
        let blocked = probes - 6 - Int(4.0 * (0.5 + 0.5 * sin(time * omega * 2.0 + 1.2)))
        let integrity = 99.72 + 0.18 * sin(time * omega + 0.4)
        let threats = 3 + Int(2.0 * (0.5 + 0.5 * sin(time * omega * 5.0 + 0.7)))
        let uptime = Int(time)
        let uptimeText = String(format: "%02d:%02d:%02d",
                                uptime / 3600, (uptime % 3600) / 60, uptime % 60)
        let seal = 0.5 + 0.5 * sin(time * omega * 0.5 + 0.3)
        let sealPct = Int(seal * 100)

        ctx.saveGState()

        if phase == .geometry {
            let lamp = s * 0.0024
            let lampPulse = 0.5 + 0.4 * CGFloat((sin(time * omega * 3.0) + 1.0) * 0.5)
            ctx.setFillColor(a(C.red, lampPulse))
            ctx.fillEllipse(in: CGRect(x: x + micro * 1.55, y: capY + micro * 0.30 - lamp,
                                       width: lamp * 2, height: lamp * 2))

            // Deterministic sparkline.
            let plotY = capY - micro * 9.0
            let bars = 36
            let step = span / CGFloat(bars)
            let base = plotY
            ctx.setStrokeColor(a(C.cyan, 0.12))
            ctx.setLineWidth(max(1, s * 0.0006))
            ctx.move(to: CGPoint(x: x - span, y: base))
            ctx.addLine(to: CGPoint(x: x, y: base))
            ctx.strokePath()
            for i in 0..<bars {
                let v = 0.16 + 0.84 * abs(sin(time * omega * 2.0 + Double(i) * 0.61))
                let bh = s * 0.022 * CGFloat(v)
                let bx = x - span + CGFloat(i) * step
                ctx.setFillColor(a(i % 7 == 5 ? C.amber : C.cyan, CGFloat(0.10 + 0.32 * v)))
                ctx.fill(CGRect(x: bx, y: base, width: max(1, step * 0.55), height: bh))
            }

            // Vault-seal progress track + fill.
            let trackY = plotY - micro * 4.4
            let barH = s * 0.0038
            let trackRect = CGRect(x: x - span, y: trackY, width: span, height: barH)
            ctx.setFillColor(a(C.blue, 0.14))
            ctx.fill(trackRect)
            let fillW = span * CGFloat(seal)
            if fillW > 0.5 {
                ctx.setFillColor(a(C.cyan, 0.55))
                ctx.fill(CGRect(x: x - span, y: trackY, width: fillW, height: barH))
            }
            ctx.setStrokeColor(a(C.ice, 0.18))
            ctx.setLineWidth(max(1, s * 0.0005))
            ctx.stroke(trackRect)
        } else {
            drawLabel(ctx, "THREAT TELEMETRY // LIVE", at: CGPoint(x: x, y: capY),
                      size: micro, color: a(C.ice, 0.34), rightAligned: true, kern: micro * 0.22)

            let rows: [(String, String)] = [
                ("PROBES", String(format: "%08d", probes)),
                ("BLOCKED", String(format: "%08d", blocked)),
                ("INTEGRITY", String(format: "%.2f%%", integrity)),
                ("THREATS", String(format: "%02d", threats)),
                ("UPTIME", uptimeText)
            ]
            for (index, row) in rows.enumerated() {
                let y = capY - micro * (2.05 + CGFloat(index) * 1.55)
                drawLabel(ctx, row.0, at: CGPoint(x: x - micro * 11.4, y: y), size: micro,
                          color: a(C.ice, 0.24), rightAligned: true, kern: micro * 0.18)
                drawLabel(ctx, row.1, at: CGPoint(x: x, y: y), size: micro,
                          color: a(index == 1 ? C.cyan : (index == 3 ? C.red : C.ice), 0.44),
                          rightAligned: true, kern: micro * 0.18)
            }

            let plotY = capY - micro * 9.0
            drawLabel(ctx, "FIREWALL ACTIVE // AES-256-GCM",
                      at: CGPoint(x: x, y: plotY - micro * 2.30), size: micro * 0.9,
                      color: a(C.ice, 0.26), rightAligned: true, kern: micro * 0.16)
            drawLabel(ctx, "VAULT SEAL \(sealPct)%",
                      at: CGPoint(x: x, y: plotY - micro * 3.85), size: micro * 0.9,
                      color: a(C.cyan, 0.38), rightAligned: true, kern: micro * 0.16)
        }

        ctx.restoreGState()
    }

    // MARK: - Falling data streams

    /// Bright packets riding down the aisle data curtains. Cheap rectangles,
    /// fully periodic, and only drawn in the service aisles so the vault stays
    /// clean.
    private static func drawDataStreams(_ ctx: CGContext, size: CGSize, time: Double) {
        let w = size.width, h = size.height
        let s = min(w, h)
        let tracks: [(CGFloat, Double, Double, CGColor)] = [
            (0.139, 1.0, 0.00, C.cyan),
            (0.156, 2.0, 0.43, C.ice),
            (0.170, 1.0, 0.71, C.cyan),
            (0.830, 2.0, 0.17, C.cyan),
            (0.846, 1.0, 0.62, C.ice),
            (0.861, 2.0, 0.31, C.amber)
        ]

        ctx.saveGState()
        ctx.setBlendMode(.screen)
        for (fx, speed, offset, color) in tracks {
            let x = w * fx
            for packet in 0..<2 {
                let p = ((time / loopDuration * speed + offset + Double(packet) * 0.5)
                    .truncatingRemainder(dividingBy: 1.0))
                let y = h * (0.690 - CGFloat(p) * 0.500)
                for k in 0..<6 {
                    let f = CGFloat(k) / 6.0
                    let alpha = 0.30 * (1.0 - f)
                    ctx.setFillColor(a(color, alpha))
                    ctx.fill(CGRect(x: x - s * 0.0010,
                                    y: y + CGFloat(k) * h * 0.0052,
                                    width: s * 0.0020,
                                    height: s * 0.0032))
                }
                ctx.setFillColor(a(C.ice, 0.60))
                ctx.fill(CGRect(x: x - s * 0.0014, y: y, width: s * 0.0028,
                                height: s * 0.0040))
                ctx.setFillColor(a(color, 0.10))
                ctx.fillEllipse(in: CGRect(x: x - s * 0.006, y: y - s * 0.004,
                                           width: s * 0.012, height: s * 0.012))
            }
        }
        ctx.restoreGState()
    }

    // MARK: - Code rain

    private static let rainGlyphs = Array("0123456789ABCDEF")
    private static let matrixGlyphs = Array("0123456789ABCDEFｱｲｳｴｵｶｷｸｹｺｻｼｽｾｿﾀﾁﾂﾃﾄ+*#$%&")

    /// Deterministic 0..1 hash of an integer, used to scatter particles and
    /// rain columns without any per-frame randomness (keeps the loop seamless).
    private static func rand(_ i: Int) -> Double {
        let x = sin(Double(i) * 12.9898 + 78.233) * 43758.5453
        return x - floor(x)
    }

    /// Glyph rain inside the two side data curtains. Heads are bright, trails
    /// fade upward. Integer speeds keep the loop seam invisible.
    private static func drawCodeRain(_ ctx: CGContext, size: CGSize, time: Double) {
        let w = size.width, h = size.height
        let s = min(w, h)
        let fontSize = s * 0.0074
        let rowStep = h * 0.0165
        let walls: [(CGFloat, Double)] = [(0.132, 0.0), (0.824, 1.0)]

        ctx.saveGState()
        for (wallIndex, wall) in walls.enumerated() {
            let wallRect = CGRect(x: w * wall.0, y: h * 0.188,
                                  width: w * 0.042, height: h * 0.502)
            ctx.saveGState()
            ctx.clip(to: wallRect)

            for col in 0..<2 {
                let x = wallRect.minX + wallRect.width * (col == 0 ? 0.20 : 0.58)
                let speed = col == 0 ? 1.0 : 2.0
                for packet in 0..<2 {
                    let phase = wall.1 * 0.37 + Double(col) * 0.53 + Double(packet) * 0.5
                    let p = ((time / loopDuration * speed + phase)
                        .truncatingRemainder(dividingBy: 1.0))
                    let headY = h * (0.690 - CGFloat(p) * 0.500)
                    for row in 0..<7 {
                        let y = headY + CGFloat(row) * rowStep
                        if y > wallRect.maxY { continue }
                        let index = (Int(time / loopDuration * 48.0)
                            + row * 3 + col * 5 + wallIndex * 7) % rainGlyphs.count
                        let glyph = String(rainGlyphs[index])
                        let alpha: CGFloat = row == 0 ? 0.60
                            : 0.20 * (1.0 - CGFloat(row) / 7.0)
                        let color = row == 0 ? C.ice : (row % 4 == 0 ? C.amber : C.cyan)
                        drawLabel(ctx, glyph, at: CGPoint(x: x, y: y), size: fontSize,
                                  color: a(color, alpha), rightAligned: false, kern: 0,
                                  glow: row == 0 ? 0.7 : 0)
                    }
                }
            }
            ctx.restoreGState()
        }
        ctx.restoreGState()
    }

    // MARK: - Bottom ticker

    private static let tickerPhrase = "0x7F3A PKT DROP 10.13.37.42 // TRACE 03 "

    private static func drawTicker(_ ctx: CGContext, size: CGSize, time: Double,
                                   phase: OverlayPhase) {
        let w = size.width, h = size.height
        let s = min(w, h)
        let size = s * 0.0069
        let kern = size * 0.14
        let chars = Array(String(repeating: tickerPhrase, count: 3))
        guard chars.count > 0 else { return }
        let window = 64
        let offset = Int(time * 4.0) % chars.count
        let text = String((0..<window).map { chars[(offset + $0) % chars.count] })
        let prefix = ">> "
        let pw = textWidth(prefix, size: size, kern: kern)
        let tw = textWidth(text, size: size, kern: kern)
        let x = w * 0.5 - (pw + tw) * 0.5
        let y = h * 0.025

        if phase == .text {
            drawLabel(ctx, prefix, at: CGPoint(x: x, y: y), size: size,
                      color: a(C.cyan, 0.55), rightAligned: false, kern: kern)
            drawLabel(ctx, text, at: CGPoint(x: x + pw, y: y), size: size,
                      color: a(C.ice, 0.26), rightAligned: false, kern: kern)
            return
        }

        ctx.setStrokeColor(a(C.cyan, 0.10))
        ctx.setLineWidth(max(1, s * 0.00055))
        ctx.move(to: CGPoint(x: x - size * 1.2, y: y - size * 0.55))
        ctx.addLine(to: CGPoint(x: x + pw + tw + size * 1.2, y: y - size * 0.55))
        ctx.strokePath()

        let lamp = s * 0.0016
        ctx.setFillColor(a(C.red, 0.65))
        ctx.fillEllipse(in: CGRect(x: x - size * 2.3 - lamp, y: y + size * 0.28 - lamp,
                                   width: lamp * 2, height: lamp * 2))
    }

