    /// Shared recessed console backing. `edge` is +1 when the accent rail sits
    /// on the left edge and -1 when it sits on the right.
    private static func drawConsolePanel(_ ctx: CGContext, rect: CGRect, edge: CGFloat,
                                        accent: CGColor, s: CGFloat) {
        ctx.saveGState()
        ctx.setBlendMode(.normal)
        let colors = [a(C.black, 0.58), a(C.black, 0.34), a(C.black, 0.02)] as CFArray
        if let g = CGGradient(colorsSpace: CGColorSpaceCreateDeviceRGB(), colors: colors,
                              locations: [0.0, 0.55, 1.0]) {
            ctx.drawLinearGradient(g, start: CGPoint(x: rect.midX, y: rect.minY),
                                   end: CGPoint(x: rect.midX, y: rect.maxY), options: [])
        }
        ctx.setBlendMode(.screen)

        let ex = edge > 0 ? rect.minX : rect.maxX
        ctx.setStrokeColor(a(accent, 0.24))
        ctx.setLineWidth(max(1, s * 0.0008))
        ctx.move(to: CGPoint(x: ex, y: rect.minY))
        ctx.addLine(to: CGPoint(x: ex, y: rect.maxY))
        ctx.strokePath()

        ctx.setStrokeColor(a(accent, 0.10))
        ctx.setLineWidth(max(1, s * 0.0006))
        ctx.move(to: CGPoint(x: rect.minX, y: rect.maxY))
        ctx.addLine(to: CGPoint(x: rect.maxX, y: rect.maxY))
        ctx.strokePath()

        for t in [CGFloat(0.06), CGFloat(0.50), CGFloat(0.94)] {
            let y = rect.minY + (rect.maxY - rect.minY) * t
            ctx.setStrokeColor(a(accent, 0.12))
            ctx.setLineWidth(max(1, s * 0.0006))
            ctx.move(to: CGPoint(x: ex, y: y))
            ctx.addLine(to: CGPoint(x: ex + edge * s * 0.007, y: y))
            ctx.strokePath()
        }
        ctx.restoreGState()
    }

    private static func drawTerminal(_ ctx: CGContext, size: CGSize, time: Double,
                                     wallClock: Date?, phase: OverlayPhase) {
        let w = size.width, h = size.height
        let s = min(w, h)
        let reading = chrono(wallClock, time: time)
        let margin = s * 0.0072
        let width = min(w * 0.132, s * 0.340)
        let x = w * 0.135
        let rect = CGRect(x: x, y: h * 0.044, width: width, height: h * 0.106)

        let micro = s * 0.0072
        let kern = micro * 0.14
        let tx = x + margin
        let headerY = h * 0.140

        if phase == .geometry {
            drawConsolePanel(ctx, rect: rect, edge: 1, accent: C.cyan, s: s)

            let lamp = s * 0.0020
            let pulse = 0.55 + 0.35 * CGFloat((sin(time * omega * 2.0) + 1.0) * 0.5)
            ctx.setFillColor(a(C.cyan, pulse))
            ctx.fillEllipse(in: CGRect(x: tx - lamp, y: headerY + micro * 0.28 - lamp,
                                       width: lamp * 2, height: lamp * 2))

            let command = shellCommands[Int(time / 6.0) % shellCommands.count]
            let prompt = "root@qtl$ " + command
            let promptY = h * 0.058
            let cursorOn = time.truncatingRemainder(dividingBy: 1.0) < 0.50
            if cursorOn {
                let cursorX = tx + textWidth(prompt, size: micro, kern: kern) + micro * 0.35
                ctx.setFillColor(a(C.ice, 0.55))
                ctx.fill(CGRect(x: cursorX, y: promptY - micro * 0.06,
                                width: micro * 0.58, height: micro * 0.88))
            }

            ctx.setStrokeColor(a(C.cyan, 0.10))
            ctx.setLineWidth(max(1, s * 0.0006))
            ctx.move(to: CGPoint(x: tx, y: h * 0.070))
            ctx.addLine(to: CGPoint(x: x + width - margin, y: h * 0.070))
            ctx.strokePath()
            return
        }

        drawLabel(ctx, "root@qtl // sentinel", at: CGPoint(x: tx + micro * 1.7, y: headerY),
                  size: micro, color: a(C.ice, 0.46), rightAligned: false, kern: kern)
        drawLabel(ctx, "tty0", at: CGPoint(x: x + width - margin, y: headerY),
                  size: micro * 0.85, color: a(C.cyan, 0.26), rightAligned: true,
                  kern: micro * 0.12)

        let start = Int(time / 2.0) % logBook.count
        for i in 0..<4 {
            let entry = logBook[(start + i) % logBook.count]
            let y = h * 0.124 - CGFloat(i) * h * 0.016
            let seconds = ((reading.secondsOfDay - (3 - i) * 2) % 86_400 + 86_400) % 86_400
            let timestamp = String(format: "%02d:%02d:%02d",
                                   seconds / 3600, (seconds % 3600) / 60, seconds % 60)
            drawLabel(ctx, timestamp, at: CGPoint(x: tx, y: y), size: micro * 0.94,
                      color: a(C.ice, 0.26), rightAligned: false, kern: kern)

            let tag = "[" + entry.0.padding(toLength: 5, withPad: " ", startingAt: 0) + "]"
            let tagX = tx + textWidth(timestamp, size: micro * 0.94, kern: kern) + micro * 0.7
            drawLabel(ctx, tag, at: CGPoint(x: tagX, y: y), size: micro * 0.94,
                      color: a(logColor(entry.0), 0.80), rightAligned: false, kern: kern)

            let msgX = tagX + textWidth(tag, size: micro * 0.94, kern: kern) + micro * 0.7
            drawLabel(ctx, entry.1, at: CGPoint(x: msgX, y: y), size: micro * 0.94,
                      color: a(C.ice, 0.44), rightAligned: false, kern: kern)
        }

        let command = shellCommands[Int(time / 6.0) % shellCommands.count]
        let prompt = "root@qtl$ " + command
        drawLabel(ctx, prompt, at: CGPoint(x: tx, y: h * 0.058), size: micro,
                  color: a(C.cyan, 0.52), rightAligned: false, kern: kern)
    }

    // MARK: - Trace route console

    private static func drawTrace(_ ctx: CGContext, size: CGSize, time: Double,
                                  phase: OverlayPhase) {
        let w = size.width, h = size.height
        let s = min(w, h)
        let margin = s * 0.0072
        let width = min(w * 0.132, s * 0.340)
        let right = w * 0.865
        let x = right - width
        let rect = CGRect(x: x, y: h * 0.044, width: width, height: h * 0.106)

        let micro = s * 0.0072
        let kern = micro * 0.14
        let rx = right - margin
        let headerY = h * 0.140

        if phase == .geometry {
            drawConsolePanel(ctx, rect: rect, edge: -1, accent: C.red, s: s)

            let lamp = s * 0.0020
            let pulse = 0.50 + 0.45 * CGFloat((sin(time * omega * 3.0) + 1.0) * 0.5)
            ctx.setFillColor(a(C.red, pulse))
            ctx.fillEllipse(in: CGRect(x: x + margin - lamp, y: headerY + micro * 0.28 - lamp,
                                       width: lamp * 2, height: lamp * 2))

            // Mini route chain with a travelling probe.
            let chainY = h * 0.077
            let chainX0 = x + margin
            let chainX1 = rx
            let nodeCount = 4
            let step = (chainX1 - chainX0) / CGFloat(nodeCount - 1)
            ctx.setStrokeColor(a(C.blue, 0.20))
            ctx.setLineWidth(max(1, s * 0.0007))
            ctx.move(to: CGPoint(x: chainX0, y: chainY))
            ctx.addLine(to: CGPoint(x: chainX1, y: chainY))
            ctx.strokePath()

            for i in 0..<nodeCount {
                let nx = chainX0 + CGFloat(i) * step
                let hostile = i == nodeCount - 1
                let r = s * 0.0024
                ctx.setFillColor(a(hostile ? C.red : C.cyan, hostile ? 0.75 : 0.45))
                ctx.fillEllipse(in: CGRect(x: nx - r, y: chainY - r, width: r * 2, height: r * 2))
                if hostile {
                    ctx.setStrokeColor(a(C.red, 0.30))
                    ctx.setLineWidth(max(1, s * 0.0006))
                    ctx.strokeEllipse(in: CGRect(x: nx - r * 2.4, y: chainY - r * 2.4,
                                                  width: r * 4.8, height: r * 4.8))
                }
            }

            let probe = (time / 2.5).truncatingRemainder(dividingBy: 1.0)
            let probeX = chainX0 + CGFloat(probe) * (chainX1 - chainX0)
            for k in 0..<4 {
                let f = CGFloat(k) / 4.0
                ctx.setFillColor(a(C.red, 0.30 * (1.0 - f)))
                ctx.fill(CGRect(x: probeX - CGFloat(k) * s * 0.0030 - s * 0.0040,
                                y: chainY - s * 0.0008, width: s * 0.0024, height: s * 0.0016))
            }
            ctx.setFillColor(a(C.red, 0.85))
            ctx.fillEllipse(in: CGRect(x: probeX - s * 0.0016, y: chainY - s * 0.0016,
                                       width: s * 0.0032, height: s * 0.0032))
            return
        }

        drawLabel(ctx, "TRACE ROUTE // 0x7F3A // CRC A3F7", at: CGPoint(x: rx, y: headerY),
                  size: micro, color: a(C.ice, 0.40), rightAligned: true, kern: kern)

        let hops: [(String, String, CGColor)] = [
            ("01  10.0.0.1      1ms", "10.0.0.1", C.ice),
            ("02  10.13.0.7     4ms", "10.13.0.7", C.ice),
            ("03  10.13.37.42   9ms", "10.13.37.42", C.red)
        ]
        for (index, hop) in hops.enumerated() {
            let y = h * 0.123 - CGFloat(index) * h * 0.015
            drawLabel(ctx, hop.0, at: CGPoint(x: rx, y: y), size: micro * 0.94,
                      color: a(hop.2, index == 2 ? 0.62 : 0.38), rightAligned: true, kern: kern)
        }

        let chainY = h * 0.077
        let chainX0 = x + margin
        let chainX1 = rx
        let nodeCount = 4
        let step = (chainX1 - chainX0) / CGFloat(nodeCount - 1)
        let labels = ["GW", "FW", "TOR", "TGT"]
        for i in 0..<nodeCount {
            let nx = chainX0 + CGFloat(i) * step
            let hostile = i == nodeCount - 1
            let label = labels[i]
            let lw = textWidth(label, size: micro * 0.78, kern: kern * 0.8)
            drawLabel(ctx, label, at: CGPoint(x: nx - lw * 0.5, y: chainY + s * 0.0070),
                      size: micro * 0.78, color: a(hostile ? C.red : C.ice, 0.28),
                      rightAligned: false, kern: kern * 0.8)
        }

        drawLabel(ctx, "[BLOCK] egress denied", at: CGPoint(x: rx, y: h * 0.058),
                  size: micro * 0.92, color: a(C.red, 0.60), rightAligned: true, kern: kern)
    }

    // MARK: - Threat badge

    private static func drawThreatBadge(_ ctx: CGContext, size: CGSize, time: Double,
                                        phase: OverlayPhase) {
        let w = size.width, h = size.height
        let s = min(w, h)
        let micro = s * 0.0074
        let cx = w * 0.5
        let kern = micro * 0.20

        let level = 3 + (Int(time / 10.0) % 2)
        let alerting = time.truncatingRemainder(dividingBy: 15.0) < 1.7

        if phase == .text {
            if !alerting {
                let caption = "DEFCON \(level) // \(level >= 4 ? "SEVERE" : "ELEVATED")"
                let cw = textWidth(caption, size: micro, kern: kern)
                drawLabel(ctx, caption, at: CGPoint(x: cx - cw * 0.5, y: h * 0.927),
                          size: micro, color: a(level >= 4 ? C.red : C.amber, 0.42),
                          rightAligned: false, kern: kern)
            }
            return
        }

        let barW = s * 0.014
        let gap = s * 0.004
        let barH = s * 0.0044
        let total = 5 * barW + 4 * gap
        let startX = cx - total * 0.5
        for i in 0..<5 {
            let lit = i < level
            let color: CGColor = alerting ? C.red : (i >= 3 ? C.red : C.amber)
            ctx.setFillColor(a(lit ? color : C.blue,
                               lit ? (alerting ? 0.78 : 0.58) : 0.10))
            ctx.fill(CGRect(x: startX + CGFloat(i) * (barW + gap), y: h * 0.936,
                            width: barW, height: barH))
        }

        // Rotating reticle around the threat bars.
        let reticle = CGPoint(x: cx, y: h * 0.939)
        let rot = time * omega * 1.0
        for i in 0..<4 {
            let ang = rot + Double(i) * Double.pi / 2.0
            ctx.setStrokeColor(a(C.blue, 0.16))
            ctx.setLineWidth(max(1, h * 0.0007))
            ctx.move(to: CGPoint(x: reticle.x + CGFloat(cos(ang)) * s * 0.030,
                                 y: reticle.y + CGFloat(sin(ang)) * s * 0.020))
            ctx.addLine(to: CGPoint(x: reticle.x + CGFloat(cos(ang)) * s * 0.040,
                                    y: reticle.y + CGFloat(sin(ang)) * s * 0.027))
            ctx.strokePath()
        }
    }

    // MARK: - Intrusion alert

    private static func drawAlert(_ ctx: CGContext, size: CGSize, time: Double,
                                  phase: OverlayPhase) {
        let w = size.width, h = size.height
        let s = min(w, h)
        let cycle = time.truncatingRemainder(dividingBy: 15.0)
        guard cycle < 1.7 else { return }
        let fadeIn = min(1.0, cycle / 0.12)
        let fadeOut = min(1.0, (1.7 - cycle) / 0.35)
        let flicker = 0.86 + 0.14 * sin(time * omega * 430.0)
        let env = CGFloat(max(0.0, fadeIn * fadeOut * flicker))
        guard env > 0.01 else { return }

        let second = Int(time / 15.0) % 2 == 1
        let text = second
            ? "!! COUNTERMEASURE ACTIVE // TRACE 10.13.37.42"
            : "!! INTRUSION ATTEMPT // SECTOR 04 // BLOCKED"
        let fontSize = s * 0.0098
        let kern = fontSize * 0.16
        let textW = textWidth(text, size: fontSize, kern: kern)

        ctx.saveGState()
        ctx.setBlendMode(.screen)

        if phase == .text {
            drawLabel(ctx, text, at: CGPoint(x: w * 0.5 - textW * 0.5, y: h * 0.923),
                      size: fontSize, color: a(C.red, 0.92 * env), rightAligned: false,
                      kern: kern, glow: 1.2)
            ctx.restoreGState()
            return
        }

        // Warning band behind the copy, pinned between the vault crown and the
        // top HUD rail so it never fights the ring labels.
        let band = [a(C.red, 0.0), a(C.red, 0.16 * env), a(C.red, 0.0)] as CFArray
        if let g = CGGradient(colorsSpace: CGColorSpaceCreateDeviceRGB(), colors: band,
                              locations: [0.0, 0.5, 1.0]) {
            ctx.saveGState()
            ctx.clip(to: CGRect(x: w * 0.20, y: h * 0.916, width: w * 0.60, height: h * 0.018))
            ctx.drawLinearGradient(g, start: CGPoint(x: w * 0.20, y: h * 0.925),
                                   end: CGPoint(x: w * 0.80, y: h * 0.925), options: [])
            ctx.restoreGState()
        }

        // The vault itself goes into lockdown: red arcs, warning ticks and a
        // hostile wash across the core.
        let core = CGPoint(x: w * 0.5, y: h * 0.555)
        let R = s * 0.285

        // Batched arcs: one path instead of three draw calls.
        let arcPath = CGMutablePath()
        for k in 0..<3 {
            let start = time * omega * 7.0 + Double(k) * Double.pi * 2.0 / 3.0
            arcPath.addArc(center: core, radius: R * 1.075,
                           startAngle: start, endAngle: start + 0.30, clockwise: false)
        }
        ctx.setLineWidth(max(1, s * 0.0022))
        ctx.setStrokeColor(a(C.red, 0.34 * env))
        ctx.addPath(arcPath)
        ctx.strokePath()

        // Batched warning ticks: hot and normal runs.
        let hotTicks = CGMutablePath()
        let coldTicks = CGMutablePath()
        for i in 0..<36 {
            let ang = Double(i) / 36.0 * Double.pi * 2.0 + time * omega * 1.0
            let hot = i % 3 == 0
            let r0 = R * 1.105
            let r1 = r0 + s * (hot ? 0.010 : 0.005)
            let path = hot ? hotTicks : coldTicks
            path.move(to: CGPoint(x: core.x + CGFloat(cos(ang)) * r0,
                                  y: core.y + CGFloat(sin(ang)) * r0))
            path.addLine(to: CGPoint(x: core.x + CGFloat(cos(ang)) * r1,
                                     y: core.y + CGFloat(sin(ang)) * r1))
        }
        ctx.setStrokeColor(a(C.red, 0.42 * env))
        ctx.setLineWidth(max(1, s * 0.0013))
        ctx.addPath(hotTicks)
        ctx.strokePath()
        ctx.setStrokeColor(a(C.red, 0.13 * env))
        ctx.setLineWidth(max(1, s * 0.0007))
        ctx.addPath(coldTicks)
        ctx.strokePath()

        // Alarm strobes on the pylon caps. These are small, so a smooth radial
        // gradient is affordable even though the full-screen wash was not.
        let lamps: [(CGFloat, CGFloat)] = [
            (0.089, 0.701), (0.911, 0.701), (0.2175, 0.516), (0.7825, 0.516)
        ]
        for lamp in lamps {
            let p = CGPoint(x: w * lamp.0, y: h * lamp.1)
            let colors = [a(C.red, 0.24 * env), a(C.red, 0.0)] as CFArray
            if let g = CGGradient(colorsSpace: CGColorSpaceCreateDeviceRGB(),
                                  colors: colors, locations: [0.0, 1.0]) {
                ctx.drawRadialGradient(g, startCenter: p, startRadius: 0,
                                       endCenter: p, endRadius: s * 0.034,
                                       options: [])
            }
        }

        // Alarm frame. Four thin filled bars per layer are far cheaper than
        // stroking a screen-sized rectangle, whose bounding box CoreGraphics
        // otherwise rasterizes in full.
        let inner = max(1, s * 0.0022)
        let outer = inner * 2.4
        for (thickness, alpha) in [(outer, 0.045), (inner, 0.11)] {
            ctx.setFillColor(a(C.red, CGFloat(alpha) * env))
            ctx.fill(CGRect(x: 0, y: 0, width: w, height: thickness))
            ctx.fill(CGRect(x: 0, y: h - thickness, width: w, height: thickness))
            ctx.fill(CGRect(x: 0, y: 0, width: thickness, height: h))
            ctx.fill(CGRect(x: w - thickness, y: 0, width: thickness, height: h))
        }
        ctx.restoreGState()
    }

    // MARK: - HUD

    private static func drawHUD(_ ctx: CGContext, size: CGSize, time: Double,
                                phase: OverlayPhase) {
        let w = size.width, h = size.height
        let s = min(w, h)
        let inset = s * 0.030
        let arm = s * 0.052

        ctx.saveGState()

        if phase == .geometry {
            let corners: [(CGPoint, CGFloat, CGFloat)] = [
                (CGPoint(x: inset, y: inset), 1, 1),
                (CGPoint(x: w - inset, y: inset), -1, 1),
                (CGPoint(x: inset, y: h - inset), 1, -1),
                (CGPoint(x: w - inset, y: h - inset), -1, -1)
            ]
            for (p, dx, dy) in corners {
                ctx.setStrokeColor(a(C.cyan, 0.26))
                ctx.setLineWidth(max(1, h * 0.0012))
                ctx.move(to: CGPoint(x: p.x, y: p.y + dy * arm))
                ctx.addLine(to: p)
                ctx.addLine(to: CGPoint(x: p.x + dx * arm, y: p.y))
                ctx.strokePath()

                ctx.setStrokeColor(a(C.cyan, 0.10))
                ctx.setLineWidth(max(1, h * 0.0007))
                for i in 1...3 {
                    let d = arm * (1.35 + CGFloat(i) * 0.40)
                    ctx.move(to: CGPoint(x: p.x + dx * d, y: p.y))
                    ctx.addLine(to: CGPoint(x: p.x + dx * (d + arm * 0.14), y: p.y))
                    ctx.move(to: CGPoint(x: p.x, y: p.y + dy * d))
                    ctx.addLine(to: CGPoint(x: p.x, y: p.y + dy * (d + arm * 0.14)))
                }
                ctx.strokePath()
            }

            let fontSize = s * 0.0098
            let topY = h - inset - arm * 0.52
            let dot = s * 0.0024
            ctx.setFillColor(a(C.cyan, 0.65))
            ctx.fillEllipse(in: CGRect(x: inset + arm * 0.16 - dot, y: topY + fontSize * 0.35 - dot,
                                       width: dot * 2, height: dot * 2))
            ctx.setFillColor(a(C.red, 0.55))
            ctx.fillEllipse(in: CGRect(x: w - inset - arm * 0.16 - dot, y: topY + fontSize * 0.35 - dot,
                                       width: dot * 2, height: dot * 2))

            // Top reticle.
            let reticle = CGPoint(x: w * 0.5, y: h - inset - arm * 0.10)
            let rot = time * omega * 1.0
            for i in 0..<4 {
                let ang = rot + Double(i) * Double.pi / 2.0
                ctx.setStrokeColor(a(C.blue, 0.16))
                ctx.setLineWidth(max(1, h * 0.0007))
                ctx.move(to: CGPoint(x: reticle.x + CGFloat(cos(ang)) * s * 0.011,
                                     y: reticle.y + CGFloat(sin(ang)) * s * 0.011))
                ctx.addLine(to: CGPoint(x: reticle.x + CGFloat(cos(ang)) * s * 0.021,
                                        y: reticle.y + CGFloat(sin(ang)) * s * 0.021))
                ctx.strokePath()
            }
        } else {
            // Minimal monospaced legends.
            let fontSize = s * 0.0098
            let topY = h - inset - arm * 0.52
            let bottomY = inset + arm * 0.30
            let titleX = inset + arm * 0.38
            if time.truncatingRemainder(dividingBy: 6.0) < 0.10 {
                drawLabel(ctx, "QUANTUM TERMINAL", at: CGPoint(x: titleX + s * 0.0016, y: topY),
                          size: fontSize, color: a(C.red, 0.20), rightAligned: false)
                drawLabel(ctx, "QUANTUM TERMINAL", at: CGPoint(x: titleX - s * 0.0016, y: topY),
                          size: fontSize, color: a(C.cyan, 0.24), rightAligned: false)
            }
            drawLabel(ctx, "QUANTUM TERMINAL", at: CGPoint(x: titleX, y: topY),
                      size: fontSize, color: a(C.ice, 0.34), rightAligned: false)
            drawLabel(ctx, "SECURE CORE // ONLINE", at: CGPoint(x: w - inset - arm * 0.38, y: topY),
                      size: fontSize, color: a(C.ice, 0.30), rightAligned: true)
            drawLabel(ctx, "AUTH 2.0 // AES-256", at: CGPoint(x: inset + arm * 0.38, y: bottomY),
                      size: fontSize, color: a(C.ice, 0.28), rightAligned: false)
            drawLabel(ctx, "INTRUSION MONITOR", at: CGPoint(x: w - inset - arm * 0.38, y: bottomY),
                      size: fontSize, color: a(C.violet, 0.42), rightAligned: true)
        }

        ctx.restoreGState()
    }

    // MARK: - Scanlines

    /// A faint CRT raster across the whole frame. Drawn as one batched path so
    /// the per-line cost stays negligible.
    private static func drawScanlines(_ ctx: CGContext, size: CGSize) {
        let w = size.width, h = size.height
        let s = min(w, h)
        let spacing = max(3, s * 0.008)
        ctx.saveGState()
        ctx.setBlendMode(.normal)
        ctx.setStrokeColor(a(C.black, 0.06))
        ctx.setLineWidth(1)
        let path = CGMutablePath()
        var y: CGFloat = 0
        while y < h {
            path.move(to: CGPoint(x: 0, y: y))
            path.addLine(to: CGPoint(x: w, y: y))
            y += spacing
        }
        ctx.addPath(path)
        ctx.strokePath()
        ctx.restoreGState()
    }

    // MARK: - Text cache

    private struct GlyphKey: Hashable {
        let text: String
        let size: CGFloat
        let kern: CGFloat
        let r: CGFloat
        let g: CGFloat
        let b: CGFloat
        let a: CGFloat
    }

    private struct WidthKey: Hashable {
        let text: String
        let size: CGFloat
        let kern: CGFloat
    }

    private static var lineCache: [GlyphKey: (CTLine, CGFloat)] = [:]
    private static var widthCache: [WidthKey: CGFloat] = [:]

    private static func cacheable(_ text: String) -> Bool {
        if text.count > 32 { return false }
        // Avoid churning the cache with per-frame telemetry counters.
        if text.count > 4 && text.allSatisfy({ $0.isNumber }) { return false }
        return true
    }

    private static func cachedLine(_ text: String, size: CGFloat, kern: CGFloat,
                                   color: CGColor) -> (CTLine, CGFloat) {
        let components = color.components ?? [0, 0, 0, 1]
        let r = components.count > 0 ? components[0] : 0
        let g = components.count > 1 ? components[1] : 0
        let b = components.count > 2 ? components[2] : 0
        let a = components.count > 3 ? components[3] : 1
        let key = GlyphKey(text: text, size: size, kern: kern, r: r, g: g, b: b, a: a)
        if let hit = lineCache[key] { return hit }

        let font = CTFontCreateWithName("Menlo" as CFString, size, nil)
        let attrs: [NSAttributedString.Key: Any] = [
            NSAttributedString.Key(kCTFontAttributeName as String): font,
            NSAttributedString.Key(kCTForegroundColorAttributeName as String): color,
            NSAttributedString.Key(kCTKernAttributeName as String): kern
        ]
        let line = CTLineCreateWithAttributedString(
            NSAttributedString(string: text, attributes: attrs))
        let width = CGFloat(CTLineGetTypographicBounds(line, nil, nil, nil))
        let value = (line, width)
        if cacheable(text) {
            if lineCache.count > 900 { lineCache.removeAll(keepingCapacity: true) }
            lineCache[key] = value
        }
        return value
    }

    private static func drawLabel(_ ctx: CGContext, _ text: String, at point: CGPoint,
                                  size: CGFloat, color: CGColor, rightAligned: Bool,
                                  kern: CGFloat? = nil, glow: CGFloat = 0) {
        let actualKern = kern ?? size * 0.16
        let (line, width) = cachedLine(text, size: size, kern: actualKern, color: color)
        let origin = CGPoint(x: rightAligned ? point.x - width : point.x, y: point.y)

        if glow > 0 {
            let sourceAlpha = color.alpha
            ctx.saveGState()
            ctx.setBlendMode(.screen)
            ctx.setTextDrawingMode(.stroke)
            for (factor, alpha) in [(CGFloat(0.075), 0.055), (CGFloat(0.030), 0.12)] {
                ctx.setLineWidth(size * factor)
                ctx.setStrokeColor(a(color, CGFloat(alpha) * glow * sourceAlpha))
                ctx.textPosition = origin
                CTLineDraw(line, ctx)
            }
            ctx.setTextDrawingMode(.fill)
            ctx.restoreGState()
        }

        ctx.textPosition = origin
        CTLineDraw(line, ctx)
    }

    private static func drawGlowLabel(_ ctx: CGContext, _ text: String, at point: CGPoint,
                                      size: CGFloat, color: CGColor, kern: CGFloat,
                                      glow: CGFloat) {
        drawLabel(ctx, text, at: point, size: size, color: color, rightAligned: false,
                  kern: kern, glow: glow)
    }

    private static func textWidth(_ text: String, size: CGFloat, kern: CGFloat) -> CGFloat {
        let key = WidthKey(text: text, size: size, kern: kern)
        if let hit = widthCache[key] { return hit }
        let font = CTFontCreateWithName("Menlo" as CFString, size, nil)
        let attrs: [NSAttributedString.Key: Any] = [
            NSAttributedString.Key(kCTFontAttributeName as String): font,
            NSAttributedString.Key(kCTKernAttributeName as String): kern
        ]
        let line = CTLineCreateWithAttributedString(
            NSAttributedString(string: text, attributes: attrs))
        let width = CGFloat(CTLineGetTypographicBounds(line, nil, nil, nil))
        if cacheable(text) {
            if widthCache.count > 600 { widthCache.removeAll(keepingCapacity: true) }
            widthCache[key] = width
        }
        return width
    }
}
